      "element_id": "prisma_2020_7_e2",
      "status": "PARTIAL",
      "chunk_id": "text_6",
      "quote": "conducted a comprehensive search of electronic databases from the date of inception to May 2023",
      "reason": "A date limit (inception to May 2023) is stated, but limits are not explicitly justified by reference to the eligibility criteria, and no other filters/limits are described."
    },
    {
      "element_id": "prisma_2020_7_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No published search filters or hedges are cited, and no adaptations of published search approaches are described."
