    {
      "element_id": "prisma_2020_7_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Translation of the search between databases is mentioned but no specific tools used for translation are specified."
    },
    {
      "element_id": "prisma_2020_7_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although 'validation and revision with the team' is mentioned, no formal validation process or validation studies of the search strategy are described."
    },
    {
      "element_id": "prisma_2020_7_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No peer review of the search strategy (e.g., PRESS) is reported."
    },
    {
      "element_id": "prisma_2020_7_e8",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "PICOS framework is mentioned for eligibility criteria (text_5), but no description of a non-PICO conceptual structure or explorations to develop the search is provided."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_8",
  "elements": [
    {
      "element_id": "prisma_2020_8_e1",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Two independent reviewers (DC & CS) screened all the articles' titles and abstracts using the predetermined eligibility criteria. After excluding irrelevant articles and duplicates, selected articles were moved to full-text review to further assess their relevance.",
      "reason": "Two reviewers screened titles/abstracts and the same reviewers proceeded to full-text review; number of reviewers per stage is reported."
    },
    {
      "element_id": "prisma_2020_8_e2",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Reviewers conducted their assessments independently, with decisions blinded from one another.",
      "reason": "Independence and blinding of reviewers during screening is explicitly reported."
    },
    {
      "element_id": "prisma_2020_8_e3",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Any disagreements were resolved by consulting a third reviewer (SAR).",
      "reason": "Disagreement resolution via a third reviewer is described."
    },
    {
      "element_id": "prisma_2020_8_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of contacting study investigators to obtain or confirm eligibility information."
    },
    {
      "element_id": "prisma_2020_8_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "Only English-language publications were included (text_7), so no translation of non-English articles was needed; no translation process is reported."
    },
    {
      "element_id": "prisma_2020_8_e6",
      "status": "PRESENT",
      "chunk_id": "text_8",
      "quote": "Covidence software was used to facilitate the screening and selection process.",
      "reason": "Automation/screening software (Covidence) is described as part of the selection process."
    },
    {
      "element_id": "prisma_2020_8_e7",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_15",
      "quote": "Marked as ineligible by automation tools (n = 0)",
      "reason": "The PRISMA flow diagram (figure_10) reports zero records removed by automation tools before screening, so no externally derived classifier was used."
    },
    {
      "element_id": "prisma_2020_8_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of internally derived classifiers used in the study selection process."
    },
    {
      "element_id": "prisma_2020_8_e9",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of ML prioritisation tools or stopping/prioritisation rules in screening; Covidence was used only to facilitate manual screening."
    },
    {
      "element_id": "prisma_2020_8_e10",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of crowdsourcing platforms used in study selection."
    },
    {
      "element_id": "prisma_2020_8_e11",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of previously screened datasets used to eliminate records."
    }
  ],
  "confidence": 92
}

{
  "item_id": "PRISMA_2020_9",
  "elements": [
    {
      "element_id": "prisma_2020_9_e1",
      "status": "MISSING",
      "chunk_id": "text_9",
      "quote": "We used the Checklist for Critical Appraisal and Data Extraction for Systematic Reviews of Prediction Modeling Studies (CHARMS) for data extraction (Moons et al., 2014).",
      "reason": "The Data Extraction section describes the CHARMS tool and piloting but never states how many reviewers collected data from each report. The two-reviewer statement in text_8 refers to screening/selection, not data extraction."
    },
    {
      "element_id": "prisma_2020_9_e2",
      "status": "MISSING",
      "chunk_id": "text_9",
      "quote": "We customized and tested the data extraction framework on several initial articles to ensure comprehensiveness and consistency.",
      "reason": "No statement about whether data extractors worked independently; independence is only reported for the screening stage (text_8)."
    },
    {
      "element_id": "prisma_2020_9_e3",
      "status": "MISSING",
      "chunk_id": "text_9",
      "quote": "For each study, we also documented the final variables used to develop the ML models.",
      "reason": "No process for resolving disagreements during data extraction is described; the third-reviewer disagreement process in text_8 applies to screening/selection only."
    },
    {
      "element_id": "prisma_2020_9_e4",
      "status": "PARTIAL",
      "chunk_id": "text_28",
      "quote": "Due to the extent and variability of missing data, we did not impute values or contact study authors but instead chose to retain these studies and highlight the issue as a gap and a limitation in the current literature.",
      "reason": "The authors explicitly state they did not contact study investigators, which addresses (by negation) the process for obtaining/confirming data from investigators, though this appears in the Limitations section rather than Methods."
    },
    {
      "element_id": "prisma_2020_9_e5",
      "status": "MISSING",
      "chunk_id": "text_9",
      "quote": "We used the Checklist for Critical Appraisal and Data Extraction for Systematic Reviews of Prediction Modeling Studies (CHARMS) for data extraction",
      "reason": "No automation tools used for data collection are described; Covidence is mentioned only for screening/selection (text_8)."
    },
    {
      "element_id": "prisma_2020_9_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence about translation of articles for data collection is provided in the retrieved text."
    },
    {
      "element_id": "prisma_2020_9_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No software or method for extracting data from figures is reported."
    },
    {
      "element_id": "prisma_2020_9_e8",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No decision rules for selecting data from multiple reports of the same study or resolving inconsistencies across reports are described."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Outcome: The primary outcome of interest was the incidence of new AF diagnoses following the application of ML methods. Secondary outcomes included those related to patients (e.g., clinical outcomes, functional improvements, quality of life, patient satisfaction, and patient knowledge), healthcare providers (e.g., performance measures, provider satisfaction, skill enhancement, and patient-provider relationship quality), and healthcare systems (e.g., access to care, cost-efficiency, safety metrics, equity, healthcare utilization, and population health indicators).",
      "reason": "Outcome domains (primary and secondary patient-, provider-, and system-related) are listed and defined in the eligibility criteria, and data extraction categories are further specified in text_9 (CHARMS outcomes, model performance, clinical outcomes)."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The Methods do not specify a time frame of measurement for each outcome domain. A time range (6 months to 5 years) is only mentioned retrospectively in the Results (text_16), not as a pre-specified data item."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No statement indicates whether all compatible results within each outcome domain (all measures, time points, analyses) were sought."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report that only a subset of compatible results was sought, so no selection process needed to be described; no evidence supports applicability."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of changes to outcome-domain inclusion, definitions, or importance during the review is reported."
    },
    {
      "element_id": "prisma_2020_10a_e6",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of changes to processes for selecting results within outcome domains is reported."
    },
    {
      "element_id": "prisma_2020_10a_e7",
      "status": "PARTIAL",
      "chunk_id": "text_9",
      "quote": "we identified model discrimination-the ability to accurately distinguish between individuals with and without AF-as a key metric to measure the performance of ML models.",
      "reason": "Model discrimination is identified as a key metric with a brief definition, but the rationale for prioritising it over other outcomes for interpreting conclusions is not fully elaborated."
    }
  ],
  "confidence": 82
}

{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Key categories extracted included study information (e.g., data source), participant details (e.g., population characteristics), outcomes (e.g., outcome type and blinding of assessment), candidate predictors (e.g., predictor type), model development (e.g., sample size, handling of missing data, and predictor selection), model performance (e.g., calibration, classification measures), and model evaluation (e.g., internal vs. external validation). In addition to these criteria, we captured further details on study design, such as the clinical question, ML method, control groups, intended use of results, validation processes, and clinical outcomes (e.g., patient-related, provider-related, and healthcare system-related). For each study, we also documented the final variables used to develop the ML models.",
      "reason": "The Data Extraction section lists the categories of variables sought (study information, participant details, outcomes, predictors, model development, performance, evaluation, and additional study design details), each defined with illustrative examples, plus the final model variables documented per study."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "PRESENT",
      "chunk_id": "text_28",
      "quote": "Regarding missing data, we recorded unreported items as 'not reported' or 'unclear' in our extraction sheet. Due to the extent and variability of missing data, we did not impute values or contact study authors but instead chose to retain these studies and highlight the issue as a gap and a limitation in the current literature.",
      "reason": "The manuscript explicitly describes the assumptions/handling for missing or unclear study information: unreported items were recorded as 'not reported' or 'unclear', with no imputation and no author contact, and studies were retained despite missing data."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "We used the Checklist for Critical Appraisal and Data Extraction for Systematic Reviews of Prediction Modeling Studies (CHARMS) for data extraction (Moons et al., 2014).",
      "reason": "The CHARMS checklist is explicitly cited as the tool used to determine which data items to collect during extraction."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "We used the Prediction Model Risk of Bias Assessment Tool (PROBAST) for quality assessment [18].",
      "reason": "The risk-of-bias tool (PROBAST) is explicitly named; CONSORT-AI and MI-CLAIM were also applied for quality/reporting assessment."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "PROBAST, which evaluates risk of bias and applicability in prognostic model studies across four domains: participants (e.g., selection bias), model predictors (e.g., bias from inconsistencies in predictor definitions and selection), outcome (e.g., bias due to outcome misclassification), and analysis (e.g., bias from inappropriate statistical methods in model development).",
      "reason": "The four PROBAST domains and example bias components assessed are specified."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PARTIAL",
      "chunk_id": "text_20",
      "quote": "Among the 15 studies, the overall risk of bias was high in 8 studies (53%)... Only one study (7%) was rated as having a low risk of bias. The remaining six studies (40%) were deemed to have an unclear risk of bias",
      "reason": "Overall risk-of-bias judgements were made and reported, but the explicit rules used to derive the overall judgement (e.g., how domain ratings combine) are not described."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "To streamline this process, we implemented the ready-to-use template by Fernandez-Felix et al., 2023 [19].",
      "reason": "An adaptation/implementation of PROBAST using a published ready-to-use template is described."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No newly developed risk-of-bias tool was used; only existing tools (PROBAST, MI-CLAIM, CONSORT-AI) were applied."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not report how many reviewers assessed risk of bias, whether they worked independently, or how disagreements were resolved."
    },
    {
      "element_id": "prisma_2020_11_e7",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence that risk-of-bias information was sought from study investigators; the process described relied on published reports only."
    },
    {
      "element_id": "prisma_2020_11_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No automation tools for risk-of-bias assessment are reported; assessment was performed manually using PROBAST."
    }
  ],
  "confidence": 88
}

{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
      "element_id": "prisma_2020_12_e1",
      "status": "PRESENT",
      "chunk_id": "text_12",
      "quote": "tabulating key effectiveness measures, with a particular focus on model performance metrics such as sensitivity, specificity, positive predictive value, accuracy, ROC-AUC, PRC-AUC, and F1 score",
      "reason": "The synthesis methods specify the measures used to present results for the model performance outcomes (sensitivity, specificity, PPV, accuracy, ROC-AUC, PRC-AUC, F1), and text_22 adds discrimination (AUC/C-index), calibration, and NNS."
    },
    {
      "element_id": "prisma_2020_12_e2",
      "status": "PRESENT",
      "chunk_id": "text_22",
      "quote": "Both metrics range from 0 to 1, with higher values (closer to 1.0) indicating better performance. C-index above 0.75 suggests strong discrimination [39]. However, for utility in clinical practice, discrimination above 0.9 is required for regulatory considerations [40,41]. ... High performance: AUC ≥ 0.9 and superiority to control. Moderate performance: AUC ≥ 0.9 or superiority to control (but not both).",
      "reason": "Thresholds for interpreting effect sizes (AUC/C-index 0.75 and 0.9; performance classification rules) are reported with cited rationale."
    },
    {
      "element_id": "prisma_2020_12_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_12",
      "quote": "Given the heterogeneity among studies and the diversity in performance metrics reported, a meta-analysis was not feasible; instead, we conducted a narrative and descriptive synthesis.",
      "reason": "No meta-analysis or quantitative synthesis was performed, so no re-expression of synthesized results into another effect measure was needed; the manuscript explicitly states meta-analysis was not feasible."
    },
    {
      "element_id": "prisma_2020_12_e4",
      "status": "PARTIAL",
      "chunk_id": "text_22",
      "quote": "For a thorough evaluation of predictive models' performance, two key metrics-calibration and discrimination-are essential. Calibration assesses how well predicted probabilities align with observed outcomes, while discrimination, often measured by AUC or C-index, reflects a model's ability to differentiate between high- and low-risk individuals",
      "reason": "The choice of discrimination/calibration metrics is explained in the discussion, but a methods-section justification for choosing these specific effect measures over alternatives (e.g., risk ratios) is not fully provided; the narrative mainly justifies why meta-analysis was not done."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_13a",
  "elements": [
    {
      "element_id": "prisma_2020_13a_e1",
      "status": "PRESENT",
